from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_autonomous_student_v431.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    required=[
        "alliance_autonomous_student_v430.py",
        "alliance_acquisition_intent_closure_v425.py",
        "alliance_automation_grammar_rescue_v423.py",
        "alliance_automation_closure_v422.py",
        "alliance_automation_truth_escalator_v421.py",
        "alliance_automation_machine_v420.py",
        "alliance_cre_championship_v410.py",
        "alliance_cre_academy_v402.py",
        "alliance_cre_academy_v401.py",
        "alliance_cre_academy_v400.py",
        REG,
    ]
    missing=[x for x in required if not (r/x).exists()]
    if missing:
        raise SystemExit("Missing cumulative files: "+", ".join(missing))

    v430=(r/"alliance_autonomous_student_v430.py").read_text(encoding="utf-8")
    checks430=[
        'VERSION = "4.3.0-ALLIANCE-AUTONOMOUS-STUDENT-V5"',
        'V430_TRAINING_HOLD_DO_NOT_FREEZE_V5',
        'alliance_v5_cases',
    ]
    absent=[x for x in checks430 if x not in v430]
    if absent:
        raise SystemExit("Current 4.3.0 source differs; refusing blind install: "+repr(absent))

    reg=r/REG
    old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v431-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)
    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")

    marker="# FOUNDATION 4.3.1 - Alliance Autonomous Student Mastery Repair"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0:
            raise SystemExit("Registrar return not found; no changes made.")
        block=r"""
    # FOUNDATION 4.3.1 - Alliance Autonomous Student Mastery Repair
    # Additive only. 4.3.0 remains intact; V5 freezes only after 4.3.1 regression PASS.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v431/status"):
            result["autonomous_v431"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v431","error":None}
        else:
            import alliance_autonomous_student_v431 as autonomous_v431
            result["autonomous_v431"] = {**autonomous_v431.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v431"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v431","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")

    chk(r/MODULE); chk(reg)
    txt=reg.read_text(encoding="utf-8")
    cumulative={"v402":"academy_v402" in txt,"v410":"championship_v410" in txt,
                "v420":"automation_v420" in txt,"v421":"automation_v421" in txt,
                "v422":"automation_v422" in txt,"v423":"automation_v423" in txt,
                "v425":"automation_v425" in txt,"v430":"autonomous_v430" in txt,
                "v431":"autonomous_v431" in txt}
    if not all(cumulative.values()):
        raise SystemExit("Cumulative verification failed: "+repr(cumulative))

    print("Alliance Autonomous Student 4.3.1 installed")
    print("Repairs: crore/crores normalization, rental requirement budget,")
    print("already-rented investment SALE, generic many-more footer grouping,")
    print("and requirement transaction relation guard")
    print("4.3.0 preserved")
    print("Fresh V5 protected until regression PASS")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v431")
    print("Backup:",bak)

if __name__=="__main__":
    main()
